                    history?: {
                        /** @enum {string} */
                        role: "user" | "assistant";
                        content: string;
                    }[];
                    /**
                     * @description Preview the SIGNED-IN visitor's demo, where an off-script message falls through to the real model (`text: null`). Default previews the anonymous one.
                     * @default false
                     */
